import {listFiles,uploadFiles,removeFile,exportFiles,decodeFiles,restoreFiles} from './media.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='motion-atlas-v1';let state={entries:{},favorites:[],custom:[]};try{state={...state,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{}
let navigation=[], nodes=new Map(), mediaURLs=[];
let catalog, leaves=[],category='',branch='',mode='cards',saved=false,selected=null;
const labels={planned:'Planned',reference:'Reference collected',building:'Building',ready:'Ready to reuse'};
const icons=['◉','◎','◇','◈','♫','≋','Aa','✳','↗','▱','⌘','⌁','◐','▨','▶','☺','▤','▧','✦','◒','▰','CC','◖'];
const descriptions=['UI interactions, kinetic type, living objects, and data in motion.','Every projection, border, route, and camera move for your next story.','Illustrations, cutouts, textures, icons, and interface building blocks.','Devices, materials, lighting rigs, and dimensional scenes.','Small details you can hear. Clicks, sweeps, impacts, and atmosphere.','Find the feeling. Beds, beats, stems, and musical moments.','Build a visual voice with type families and typography systems.','Connect every scene with intention. Reveals, cuts, and finishing effects.','A vocabulary of visual approaches, creators, and motion techniques.','Reusable sequences for stories, launches, explainers, and social videos.','The foundations: camera, lighting, motion, and delivery.','Keep reusable components and rendering techniques within reach.','Shape the mood with series-inspired grades, filter families, LUTs, and color controls.','Paper, film, natural surfaces, digital patterns, and animated texture layers.','Real-world footage by subject, shot type, and storytelling purpose.','Reaction clips, visual punchlines, and comedic cutaways.','Historic footage, documents, and traceable evidence for visual stories.','Portraits, product images, cutouts, and layered photo preparations.','Practical elements, masks, tracking, and integrated visual effects.','Color palettes, composition recipes, and reusable brand ingredients.','Creator story structures, reference videos, scripts, and timecoded visual breakdowns.','Readable captions, translations, and accessible video variants.','Voice direction, narration takes, pronunciation, and audio alignment.'];
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function safeURL(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{notify('Storage is full. Export your progress now.');return false}}
function flatten(n,path=[],ancestors=[]){const p=[...path,n.name],record={...n,path:p,category:p[0],ancestors};nodes.set(n.id,record);if(n.children)n.children.forEach(x=>flatten(x,p,[...ancestors,n.id]));else leaves.push(record)}
function rebuild(){leaves=[];nodes=new Map();navigation=structuredClone(catalog.categories);for(const entry of state.custom){if(entry.category==='Storytelling and editing'){entry.category='Storytelling';entry.path[0]='Storytelling'}let parent=navigation.find(x=>x.name===entry.category);if(!parent)continue;for(const name of entry.path.slice(1,-1)){let next=parent.children.find(x=>x.name===name&&x.children);if(!next){next={id:parent.id+'/personal/'+encodeURIComponent(name),name,children:[]};parent.children.push(next)}parent=next}parent.children.push({...entry})}navigation.forEach(x=>flatten(x))}
function merged(e){return {...e,...state.entries[e.id]}}
function matches(e){const v=merged(e),q=$('#search').value.toLowerCase().trim();return (!category||e.category===category)&&(!branch||e.ancestors.includes(branch))&&(!saved||state.favorites.includes(e.id))&&(!$('#status').value||v.status===$('#status').value)&&(!q||q.split(/\s+/).every(term=>[...e.path,v.notes,v.creator,v.script,v.visuals,v.structure,...(v.tags||[])].join(' ').toLowerCase().includes(term)))}
function badge(status){return el('span','badge '+status,labels[status]||'Planned')}
function stats(){const a=leaves.map(merged),ref=a.filter(x=>x.references?.length||x.attachmentCount).length,ready=a.filter(x=>x.status==='ready').length;$('#stat-total').textContent=leaves.length.toLocaleString();$('#all-count').textContent=leaves.length;$('#stat-categories').textContent=catalog.categories.length;$('#stat-ref').textContent=ref;$('#stat-ready').textContent=ready;$('#progress').style.width=(100*ready/a.length)+'%';$('#progress-caption').textContent=ready?`${ready} of ${a.length} entries ready to reuse.`:'Every great library starts with one reference.'}
function nav(){const box=$('#categories');box.replaceChildren();catalog.categories.forEach((c,i)=>{const b=el('button','nav'+(category===c.name?' active':''));b.append(el('span','nav-icon',icons[i]),el('span','',c.name),el('b','',leaves.filter(x=>x.category===c.name).length));b.onclick=()=>choose(c.name);box.append(b)});$('.all').classList.toggle('active',!category);}
function choose(name){category=name;branch='';$('#search').value='';nav();render()}
function collect(n){return leaves.filter(x=>x.ancestors.includes(n.id))}
function cards(folders){const wrap=el('div','cards');folders.forEach((n,i)=>{const entries=collect(n).filter(matches);if(!entries.length)return;const b=el('button','collection-card'),art=el('div','card-art');art.style.setProperty('--tone',['#d5f99a','#afc5f4','#e6b99d','#c4b0eb'][i%4]);art.append(el('span','card-index',String(i+1).padStart(2,'0')),el('span','glyph',icons[i%icons.length]),el('span','card-corner','↗'));const body=el('div','card-body');const topIndex=navigation.findIndex(x=>x.id===n.id);body.append(el('h3','',n.name),el('p','',topIndex>=0?descriptions[topIndex]:n.children.slice(0,4).map(x=>x.name).join(' · ')));const meta=el('div','card-meta');meta.append(el('span','',`${n.children.filter(x=>x.children).length} folders · ${entries.length} entries`),el('span','',entries.filter(x=>merged(x).status==='ready').length+' ready'));body.append(meta);b.append(art,body);b.onclick=()=>{const item=nodes.get(n.id);category=item.category;branch=item.ancestors.length?n.id:'';nav();render()};wrap.append(b)});return wrap}
function entryCards(entries){const wrap=el('div','entry-grid');entries.forEach(e=>{const b=el('button','entry-card');b.append(badge(merged(e).status),el('strong','',(state.favorites.includes(e.id)?'★ ':'')+e.name),el('small','',e.path.slice(1,-1).join(' / ')));b.onclick=()=>openEntry(e);wrap.append(b)});return wrap}
function tree(entries){const visible=new Set(entries.map(x=>x.id)),wrap=el('div','tree-root');function build(n,parent,depth){if(!n.children){if(!visible.has(n.id))return;const e=nodes.get(n.id),b=el('button','tree-leaf');b.append(el('span','',(state.favorites.includes(e.id)?'★ ':'')+e.name),badge(merged(e).status));b.onclick=()=>openEntry(e);parent.append(b);return}const count=collect(n).filter(x=>visible.has(x.id)).length;if(!count)return;const d=el('details'),summary=el('summary','',n.name);summary.append(el('small','',count));d.open=!!$('#search').value||!!category&&depth===0;d.append(summary);n.children.forEach(x=>build(x,d,depth+1));parent.append(d)}const current=branch?nodes.get(branch):nodes.get(navigation.find(x=>x.name===category)?.id);(current?current.children:navigation).forEach(n=>build(n,wrap,0));return wrap}
function render(){stats();const entries=leaves.filter(matches),current=branch?nodes.get(branch):nodes.get(navigation.find(x=>x.name===category)?.id);$('#result-count').textContent=entries.length.toLocaleString()+' entries'+(category?' in '+category:' across your atlas');$('#section-heading').textContent=current?.name||(saved?'Saved for later':'Explore the collection');$('#section-subtitle').textContent=category==='Storytelling'?'Study the hook, progression, script, visuals, and payoff.':category==='Styles and inspiration'?'Study the visual editing: typography, layouts, camera, color, and sound.':category?'Open a folder, then explore its subfolders and entries.':'Go broad. Get specific. Find what’s next.';const crumbs=$('#folder-breadcrumbs');crumbs.replaceChildren();if(current){const home=el('button','','All collections');home.onclick=()=>choose('');crumbs.append(home);for(const id of [...current.ancestors,current.id]){const item=nodes.get(id);crumbs.append(el('span','','/'));const b=el('button','',item.name);b.onclick=()=>{category=item.category;branch=item.ancestors.length?item.id:'';nav();render()};crumbs.append(b)}}const content=$('#content');content.replaceChildren();if(!entries.length){const empty=el('div','empty');empty.append(el('strong','','No entries found'),el('span','','Try another search or clear your filters.'));content.append(empty);return}if(mode==='tree')content.append(tree(entries));else if(saved||$('#search').value||$('#status').value)content.append(entryCards(entries));else{const children=current?current.children:navigation;const folders=children.filter(x=>x.children),direct=children.filter(x=>!x.children).map(x=>nodes.get(x.id));if(folders.length)content.append(cards(folders));if(direct.length)content.append(entryCards(direct))}}
function openEntry(e){selected=e;const v=merged(e);$('#entry-title').textContent=e.name;$('#entry-path').textContent=e.path.slice(0,-1).join(' / ');$('#entry-status').value=v.status;$('#entry-priority').value=v.priority||'normal';$('#entry-refs').value=(v.references||[]).map(x=>typeof x==='string'?x:x.url).join('\n');$('#entry-preview').value=v.preview||'';$('#entry-code').value=v.code||'';$('#entry-license').value=v.license||'';$('#entry-notes').value=v.notes||'';$('#entry-study-type').value=v.studyType||(e.category==='Storytelling'?'storytelling':e.category==='Styles and inspiration'?'editing':'asset');$('#entry-creator').value=v.creator||'';$('#entry-script').value=v.script||'';$('#entry-visuals').value=v.visuals||'';$('#entry-structure').value=v.structure||'';void renderMedia(e.id);$('#bookmark').textContent=state.favorites.includes(e.id)?'★ Saved for later':'☆ Save for later';const links=$('#entry-links');links.replaceChildren();[['Open preview',v.preview],['Open code',v.code]].forEach(([name,url])=>{const safe=safeURL(url);if(safe){const a=el('a','',name+' ↗');a.href=safe;a.target='_blank';a.rel='noopener';links.append(a)}});$('#detail').showModal()}
$('#entry-form').onsubmit=e=>{e.preventDefault();const references=$('#entry-refs').value.split('\n').map(x=>x.trim()).filter(Boolean);if(references.some(x=>!safeURL(x))){notify('Reference links must be valid HTTP or HTTPS URLs.');return}state.entries[selected.id]={...state.entries[selected.id],studyType:$('#entry-study-type').value,creator:$('#entry-creator').value.trim(),script:$('#entry-script').value,visuals:$('#entry-visuals').value,structure:$('#entry-structure').value,status:$('#entry-status').value,priority:$('#entry-priority').value,references,preview:$('#entry-preview').value.trim()||null,code:$('#entry-code').value.trim()||null,license:$('#entry-license').value.trim()||null,notes:$('#entry-notes').value.trim(),updatedAt:new Date().toISOString()};persist();$('#detail').close();render();notify('Entry saved in this browser. Export to back it up.')};
$('#bookmark').onclick=()=>{const id=selected.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();$('#bookmark').textContent=state.favorites.includes(id)?'★ Saved for later':'☆ Save for later';render()};$('#close').onclick=()=>$('#detail').close();
$('#search').oninput=()=>render();$('#status').onchange=()=>render();$('#favorites').onclick=()=>{saved=!saved;$('#favorites').classList.toggle('saved-active',saved);$('#favorites').setAttribute('aria-pressed',saved);render()};$('#grid').onclick=()=>{mode='cards';$('#grid').classList.add('selected');$('#tree').classList.remove('selected');render()};$('#tree').onclick=()=>{mode='tree';$('#tree').classList.add('selected');$('#grid').classList.remove('selected');render()};$('.all').onclick=()=>choose('');
$('#export').onclick=async()=>{const b=$('#export');b.disabled=true;b.textContent='Preparing backup…';try{const mediaFiles=await exportFiles();const data={format:'motion-atlas-progress',version:1,exportedAt:new Date().toISOString(),...state,mediaFiles};const u=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=el('a');a.href=u;a.download='motion-atlas-library-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);notify(`Backup exported with ${mediaFiles.length} uploaded files.`)}catch(error){notify('Backup failed: '+error.message)}finally{b.disabled=false;b.textContent='Export library backup ↗'}};
$('#import').onclick=()=>$('#file').click();
$('#file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>350*1024*1024)throw Error('Backup exceeds the 350 MB import limit.');const data=JSON.parse(await file.text());if(data.format!=='motion-atlas-progress'||data.version!==1||!data.entries||!Array.isArray(data.favorites)||!Array.isArray(data.custom))throw Error('Choose a Motion Atlas backup.');const known=new Set(leaves.map(x=>x.id));for(const c of data.custom){if(c.category==='Storytelling and editing'){c.category='Storytelling';c.path[0]='Storytelling'}if(typeof c.id!=='string'||typeof c.name!=='string'||!Array.isArray(c.path)||c.path.length<4||!catalog.categories.some(x=>x.name===c.category))throw Error('Invalid custom entry.');known.add(c.id)}for(const [id,v]of Object.entries(data.entries)){if(!known.has(id)||!v||!Object.hasOwn(labels,v.status)||v.references&&!Array.isArray(v.references))throw Error('Invalid entry data.')}const media=decodeFiles(data.mediaFiles||[],known);const next={entries:{...state.entries,...data.entries},favorites:[...new Set([...state.favorites,...data.favorites.filter(x=>known.has(x))])],custom:[...new Map([...state.custom,...data.custom].map(x=>[x.id,x])).values()]};const serialized=JSON.stringify(next);localStorage.setItem(KEY,serialized);try{await restoreFiles(media)}catch(error){localStorage.setItem(KEY,JSON.stringify(state));throw error}state=next;rebuild();nav();render();notify(`Backup merged with ${media.length} uploaded files.`)}catch(error){notify(error.message||'Could not import that backup.')}finally{e.target.value=''}};
$('#add').onclick=()=>{const current=branch?nodes.get(branch):null;$('#new-category').value=category||catalog.categories[0].name;$('#new-section').value=current?.path[1]||'Personal additions';$('#new-family').value=current?.path[2]||'To organize';$('#new-subfolder').value=current?.path.slice(3).join(' / ')||'';$('#new-dialog').showModal()};$('#new-cancel').onclick=()=>$('#new-dialog').close();$('#new-form').onsubmit=e=>{e.preventDefault();const name=$('#new-name').value.trim(),c=$('#new-category').value,section=$('#new-section').value.trim(),family=$('#new-family').value.trim();if(!name||!section||!family)return;const entry={id:'custom/'+crypto.randomUUID(),name,category:c,path:[c,section,family,...$('#new-subfolder').value.split('/').map(x=>x.trim()).filter(Boolean),name],status:'planned',priority:'normal',references:[],notes:'',custom:true};state.custom.push(entry);persist();rebuild();$('#new-dialog').close();$('#new-name').value='';choose(c);mode='tree';$('#tree').click();notify('New entry added to your collection.')};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();$('#search').focus()}});
try{const response=await fetch('catalog.json');if(!response.ok)throw Error('The catalog could not be loaded.');catalog=await response.json();rebuild();catalog.categories.forEach(c=>{const o=el('option','',c.name);o.value=c.name;$('#new-category').append(o)});nav();render()}catch(err){$('#error').hidden=false;$('#error').textContent=err.message+' Serve this folder with a local HTTP server instead of opening index.html directly.'}

function clearMediaURLs(){mediaURLs.forEach(url=>URL.revokeObjectURL(url));mediaURLs=[]}
async function renderMedia(entryId){const list=$('#media-list'),viewer=$('#media-viewer');clearMediaURLs();list.replaceChildren(el('p','','Loading files…'));viewer.replaceChildren();try{const files=await listFiles(entryId);if(selected?.id!==entryId)return;list.replaceChildren();if(!files.length){list.append(el('p','media-empty','No files yet. Add a reference video, script, or storyboard.'));return}for(const file of files){const row=el('div','media-file'),info=el('div');info.append(el('strong','',file.name),el('small','',`${file.role||'Asset'} · ${(file.size/1024/1024).toFixed(2)} MB`));const controls=el('div');const url=URL.createObjectURL(file.blob);mediaURLs.push(url);const download=el('a','','Download');download.href=url;download.download=file.name;controls.append(download);const type=file.type||'';if(/^(video|audio)\//.test(type)||/^image\/(png|jpeg|webp|gif|avif)$/.test(type)||/\.(txt|md|json|csv|srt|vtt|tsx|jsx|js|ts|html|css)$/i.test(file.name)){const view=el('button','','View');view.type='button';view.onclick=async()=>{viewer.replaceChildren();if(type.startsWith('video/')||type.startsWith('audio/')){const media=el(type.startsWith('video/')?'video':'audio');media.controls=true;media.preload='metadata';media.src=url;viewer.append(media)}else if(type.startsWith('image/')){const image=el('img');image.src=url;image.alt=file.name;viewer.append(image)}else{if(file.size>2*1024*1024){notify('Download large text files to view them.');return}viewer.append(el('pre','',await file.blob.text()))}};controls.append(view)}const remove=el('button','','Remove');remove.type='button';remove.onclick=async()=>{try{await removeFile(file.id);state.entries[entryId]={...state.entries[entryId],attachmentCount:(await listFiles(entryId)).length};persist();render();await renderMedia(entryId);notify('File removed from this device.')}catch(error){notify(error.message)}};controls.append(remove);row.append(info,controls);list.append(row)}}catch(error){list.replaceChildren(el('p','','Files unavailable: '+error.message))}}
$('#upload-files').onclick=()=>$('#entry-files').click();
$('#entry-files').onchange=async e=>{const files=[...e.target.files],entryId=selected?.id;if(!files.length||!entryId)return;const button=$('#upload-files');button.disabled=true;button.textContent='Adding files…';try{await uploadFiles(entryId,files,$('#file-role').value);const existing=state.entries[entryId]||{};state.entries[entryId]={...existing,attachmentCount:(await listFiles(entryId)).length,status:existing.status&&existing.status!=='planned'?existing.status:'reference'};persist();if(selected?.id===entryId){if($('#entry-status').value==='planned')$('#entry-status').value='reference';await renderMedia(entryId)}render();notify(`${files.length} files saved on this device. Export a backup to keep them.`)}catch(error){notify('Could not save files: '+error.message)}finally{button.disabled=false;button.textContent='+ Add files';e.target.value=''}};
$('#detail').addEventListener('close',()=>{const media=$('#media-viewer video, #media-viewer audio');media?.pause();clearMediaURLs()});
